/**
 * Validate a Lucide icon slug against the curated project list.
 */
function happywood_sanitize_lucide_icon_slug( string $slug ): string {

	$slug    = sanitize_key( $slug );
	$choices = happywood_get_lucide_icon_choices();

	return array_key_exists( $slug, $choices ) ? $slug : '';
}
